90	static int ft6146_i2c_read(struct i2c_master_s *i2c,
91	                           uint8_t reg, uint8_t *buf, uint8_t len)
92	{
93	  struct i2c_msg_s msgs[2];
94	  int ret;
95	
96	  msgs[0].addr      = FT6146_DEV_ADDR;
97	  msgs[0].frequency = FT6146_I2C_DEF_FREQ;
98	  msgs[0].flags     = I2C_M_NOSTOP;
99	  msgs[0].buffer    = &reg;
100	  msgs[0].length    = 1;
101	
102	  msgs[1].addr      = FT6146_DEV_ADDR;
103	  msgs[1].frequency = FT6146_I2C_DEF_FREQ;
104	  msgs[1].flags     = I2C_M_READ | I2C_M_NOSTART;
105	  msgs[1].buffer    = buf;
106	  msgs[1].length    = len;
107	
108	  ret = I2C_TRANSFER(i2c, msgs, 2);
109	  return ret < 0 ? ret : OK;
110	}
