112	static void ft6146_data_worker(void *param)
113	{
114	  struct ft6146_touch_lowerhalf_s *ft6146 =
115	    (struct ft6146_touch_lowerhalf_s *)param;
116	  struct touch_sample_s sample;
117	  uint8_t buf[5] = {0};
118	  uint8_t touch_num;
119	  int ret;
120	
121	  ret = ft6146_i2c_read(ft6146->i2c, FT6146_REG_TD_STATUS, buf, sizeof(buf));
122	  if (ret < 0)
123	    {
124	      ierr("ft6146: read touch data failed: %d\n", ret);
125	      return;
126	    }
127	
128	  touch_num = buf[0] & 0x0f;
129	
130	  sample.npoints = 1;
131	  if (touch_num > 0)
132	    {
133	      ft6146->last_x = ((uint16_t)(buf[1] & 0x0f) << 8) | buf[2];
134	      ft6146->last_y = ((uint16_t)(buf[3] & 0x0f) << 8) | buf[4];
135	      sample.point[0].flags = TOUCH_DOWN;
136	    }
137	  else
138	    {
139	      sample.point[0].flags = TOUCH_UP;
140	    }
141	
142	  sample.point[0].x = ft6146->last_x;
143	  sample.point[0].y = ft6146->last_y;
144	
145	  touch_event(ft6146->lower.priv, &sample);
146	}
