186	    {
187	      ierr("ft6146: read id_l failed: %d\n", ret);
188	      return ret;
189	    }
190	
191	  iinfo("ft6146 id_h=0x%02x id_l=0x%02x\n", id_h, id_l);
192	
193	  ret = sifli_gpio_set_event(ft6146->pin_irq, false, true,
194	                             ft6146_irq_handler, ft6146);
195	  if (ret < 0)
196	    {
197	      ierr("ft6146: irq event setup failed: %d\n", ret);
198	      return ret;
199	    }
200	
