217	    /* Defer CJK font creation to the LVGL thread (show_screen_async_cb).
218	     * Creating a FreeType font here — from the main thread — causes
219	     * FT_Err_Invalid_Size_Handle (0x55) because the FreeType size
220	     * object races with the LVGL render thread.  Use Montserrat as
221	     * a safe placeholder until the screen is shown. */
222	    s_state.font = NULL;
223	    lv_obj_set_style_text_font(s_state.screen, &lv_font_montserrat_14, 0);
