231	        syslog(LOG_ERR, "[%s] chat_list create failed\n", TAG);
232	        ret = -EIO;
233	        goto cleanup;
234	    }
235	
236	    lv_obj_set_size(s_state.chat_list,
237	        LVGL_UI_SCREEN_W - 2 * LVGL_UI_PADDING_H, chat_h);
238	    lv_obj_align(s_state.chat_list, LV_ALIGN_TOP_MID, 0, LVGL_UI_PADDING_TOP);
239	    lv_obj_set_scroll_dir(s_state.chat_list, LV_DIR_VER);
240	    lv_obj_set_flex_flow(s_state.chat_list, LV_FLEX_FLOW_COLUMN);
241	    lv_obj_set_style_pad_row(s_state.chat_list, LVGL_UI_CHAT_GAP, 0);
242	    lv_obj_set_style_bg_opa(s_state.chat_list, LV_OPA_TRANSP, 0);
243	    lv_obj_set_style_border_width(s_state.chat_list, 0, 0);
244	    lv_obj_set_style_pad_left(s_state.chat_list, 4, 0);
245	    lv_obj_set_style_pad_right(s_state.chat_list, 4, 0);
246	    lv_obj_set_style_pad_top(s_state.chat_list, 4, 0);
247	    lv_obj_set_style_pad_bottom(s_state.chat_list, 4, 0);
