354	int lvgl_ui_channel_start(void)
355	{
356	    if (!s_state.initialized) {
357	        syslog(LOG_ERR, "[%s] start: not initialized\n", TAG);
358	        return -EINVAL;
359	    }
360	
361	    /* Idempotent: already running */
362	    if (s_state.running) {
363	        return 0;
364	    }
365	
366	    s_state.running = true;
367	
368	    /* No dedicated UI thread needed — the system's miwear LVGL event
369	     * loop already calls lv_timer_handler() which processes our widgets.
370	     * We only need to mark ourselves as running so send/PTT callbacks
371	     * know the channel is active. */
372	
373	    syslog(LOG_INFO, "[%s] started\n", TAG);
374	    return 0;
375	}
