694	static void ptt_btn_event_cb(lv_event_t* e)
695	{
696	    lv_event_code_t code = lv_event_get_code(e);
697	
698	    /* Single-click toggle: first click starts recording, second stops */
699	    if (code != LV_EVENT_CLICKED) {
700	        return;
701	    }
702	
703	    pthread_mutex_lock(&s_state.lock);
704	
705	    if (s_state.is_processing) {
706	        pthread_mutex_unlock(&s_state.lock);
707	        return;
708	    }
709	
710	    if (!s_state.is_recording) {
711	        /* First click: start recording */
712	        int ret = voice_channel_start();
713	        if (ret != 0) {
714	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
715	            pthread_mutex_unlock(&s_state.lock);
716	            chat_view_add_message("录音启动失败", false);
717	            return;
718	        }
719	
720	        s_state.is_recording = true;
721	        pthread_mutex_unlock(&s_state.lock);
722	
723	        recording_indicator_start();
724	    } else {
725	        /* Second click: stop recording and process */
726	        s_state.is_recording = false;
727	        s_state.is_processing = true;
728	        pthread_mutex_unlock(&s_state.lock);
729	
730	        recording_indicator_show_processing();
731	
732	        /* Stop recording and get ASR text synchronously */
733	        char asr_text[LVGL_UI_MSG_MAX_LEN];
734	        int ret = voice_channel_stop_with_text(asr_text,
735	            sizeof(asr_text));
736	
737	        if (ret != 0) {
738	            syslog(LOG_ERR,
739	                "[%s] voice_channel_stop_with_text failed (rc=%d)\n",
740	                TAG, ret);
741	            goto done;
742	        }
743	
744	        if (asr_text[0] == '\0') {
745	            chat_view_add_message("未识别到语音", false);
746	            goto done;
747	        }
748	
749	        /* Construct inbound message with channel="lvgl_ui" */
750	        agent_msg_t msg;
751	
752	        memset(&msg, 0, sizeof(msg));
753	        strncpy(msg.channel, AGENT_CHAN_LVGL_UI,
754	            sizeof(msg.channel) - 1);
755	        msg.channel[sizeof(msg.channel) - 1] = '\0';
756	        strncpy(msg.chat_id, "lvgl_ui",
757	            sizeof(msg.chat_id) - 1);
758	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
759	
760	        msg.content = strdup(asr_text);
761	        if (!msg.content) {
762	            syslog(LOG_ERR, "[%s] strdup failed\n", TAG);
763	            goto done;
764	        }
765	
766	        if (message_bus_push_inbound(&msg) != 0) {
767	            syslog(LOG_ERR,
768	                "[%s] message_bus_push_inbound failed\n", TAG);
769	            free(msg.content);
770	            msg.content = NULL;
771	            chat_view_add_message("发送失败", false);
772	            goto done;
773	        }
774	
775	        chat_view_add_message(asr_text, true);
776	
777	    done:
778	        pthread_mutex_lock(&s_state.lock);
779	        s_state.is_processing = false;
780	        pthread_mutex_unlock(&s_state.lock);
781	        recording_indicator_stop();
782	    }
783	}
