int tool_show_popup_execute(const char *input_json, char *output, size_t output_size)
{
    cJSON *root = cJSON_Parse(input_json);
    if (!root) {
        snprintf(output, output_size, "{\"error\":\"Invalid JSON\"}");
        return ERROR;
    }

    const char *title = cJSON_GetStringValue(
        cJSON_GetObjectItem(root, "title"));
    const char *content = cJSON_GetStringValue(
        cJSON_GetObjectItem(root, "content"));

    if (!title) title = "Notification";
    if (!content) content = "";

    /* Allocate popup data for async callback */
    popup_data_t *popup_data = malloc(sizeof(popup_data_t));
    if (!popup_data) {
        cJSON_Delete(root);
        snprintf(output, output_size, "{\"error\":\"Memory allocation failed\"}");
        return ERROR;
    }

    strncpy(popup_data->title, title, sizeof(popup_data->title) - 1);
    popup_data->title[sizeof(popup_data->title) - 1] = '\0';
    strncpy(popup_data->content, content, sizeof(popup_data->content) - 1);
    popup_data->content[sizeof(popup_data->content) - 1] = '\0';

    cJSON_Delete(root);

    /* Schedule popup creation in LVGL thread */
    lv_result_t res = lv_async_call(popup_async_cb, popup_data);
    if (res != LV_RESULT_OK) {
        free(popup_data);
        snprintf(output, output_size, "{\"error\":\"lv_async_call failed\"}");
        return ERROR;
    }

    snprintf(output, output_size,
             "{\"status\":\"ok\",\"title\":\"%s\"}", title);
    return OK;
}

